cd [local path redacted] && E=target/release/easel && cat > [local path redacted] <<'EOF'
-- retouch: the snow lips at the stones' feet scumbled clean, and the shadow carried up to the stones
local ring = (v:visible("bodies"):grow(6) - v:visible("bodies")) * vs:cast_shadow{soft=2.2}
glaze(ring, {color="#6a7090", coats=0.3, view=vs})
local tw = noise{seed=121, period=18}
work(footd:shrink(0.5), {hand="scumble", tool="filbert 3", length={5, 14}, coverage=2.6, clip=footd, angle=0.02,
  color_over=function(x, y, under)
    local snow = mix("#e9e1cf", "#a9adc0", math.max(smoothstep(548, 600, x) * (1 - smoothstep(600, 620, x)), smoothstep(690, 745, x) * 0.8))
    return shift(mix(under, snow, 0.75), 0.015 * tw(x, y), 0, 0)
  end})
EOF
timeout 300 $E edit 19 --insert -f [local path redacted] && timeout 60 $E look --crop 540,440,800,600
